<template>
  <div class="module-wrap" :class="{ 'm-console': isMobile }">
    <!-- 游戏管理 -->
    <template v-if="section==='games'">
      <div class="module-tabs"><button :class="{on:gameView==='directory'}" @click="gameView='directory'">游戏目录</button><button :class="{on:gameView==='tasks'}" @click="gameView='tasks'">同步与回填</button></div>
      <template v-if="gameView==='directory'">
        <div class="module-card filterbar"><el-input v-model="gameQuery" clearable placeholder="搜索名称或 AppID" @keyup.enter="loadGames(1)"/><el-select v-model="gamePlatform" placeholder="全部平台" @change="loadGames(1)"><el-option label="全部平台" value=""/><el-option v-for="p in platforms" :key="p.value" :label="p.label" :value="p.value"/></el-select><el-select v-model="gameStatus" placeholder="全部同步状态" @change="gameOffers='';loadGames(1)"><el-option label="全部同步状态" value=""/><el-option label="未探测" value="pending"/><el-option label="已同步" value="synced"/><el-option label="免费" value="free"/><el-option label="未发售" value="coming_soon"/><el-option label="锁国区" value="region_locked"/><el-option label="国区无价" value="no_price"/><el-option label="国区不可售" value="not_found"/><el-option label="其他" value="other"/></el-select><el-select v-model="gameRating" placeholder="全部内容分级" @change="loadGames(1)"><el-option label="全部内容分级" value=""/><el-option label="成人（18+）" value="adult"/><el-option label="成熟" value="mature"/><el-option label="未标注" value="none"/></el-select><el-button :loading="loading" @click="refreshGames">刷新</el-button><el-button @click="mergeDialog=true">高级</el-button></div>
        <div class="metric-grid clickable-grid"><div class="metric-card" :class="{on:activeMetric==='all'}" role="button" tabindex="0" @click="clickMetric('all')" @keydown.enter="clickMetric('all')"><span>目录游戏</span><strong>{{ gameStats.total||0 }}</strong></div><div class="metric-card" :class="{on:activeMetric==='synced'}" role="button" tabindex="0" @click="clickMetric('synced')" @keydown.enter="clickMetric('synced')"><span>已同步</span><strong>{{ gameStats.synced||0 }}</strong></div><div class="metric-card" :class="{on:activeMetric==='pending'}" role="button" tabindex="0" @click="clickMetric('pending')" @keydown.enter="clickMetric('pending')"><span>未探测</span><strong>{{ gameStats.pendingProbe||0 }}</strong></div><div class="metric-card" :class="{on:activeMetric==='free'}" role="button" tabindex="0" @click="clickMetric('free')" @keydown.enter="clickMetric('free')"><span>免费</span><strong>{{ gameStats.free||0 }}</strong></div><div class="metric-card" :class="{on:activeMetric==='coming_soon'}" role="button" tabindex="0" @click="clickMetric('coming_soon')" @keydown.enter="clickMetric('coming_soon')"><span>未发售</span><strong>{{ gameStats.comingSoon||0 }}</strong></div><div class="metric-card" :class="{on:activeMetric==='region_locked'}" role="button" tabindex="0" @click="clickMetric('region_locked')" @keydown.enter="clickMetric('region_locked')"><span>锁国区</span><strong>{{ gameStats.regionLocked||0 }}</strong></div><div class="metric-card" :class="{on:activeMetric==='no_price'}" role="button" tabindex="0" @click="clickMetric('no_price')" @keydown.enter="clickMetric('no_price')"><span>国区无价</span><strong>{{ gameStats.noPrice||0 }}</strong></div><div class="metric-card" :class="{on:activeMetric==='not_found'}" role="button" tabindex="0" @click="clickMetric('not_found')" @keydown.enter="clickMetric('not_found')"><span>国区不可售</span><strong>{{ gameStats.notFound||0 }}</strong></div><div class="metric-card" :class="{on:activeMetric==='other'}" role="button" tabindex="0" @click="clickMetric('other')" @keydown.enter="clickMetric('other')"><span>其他</span><strong>{{ gameStats.other||0 }}</strong></div><div class="metric-card" :class="{on:activeMetric==='adult'}" role="button" tabindex="0" @click="clickMetric('adult')" @keydown.enter="clickMetric('adult')"><span>成人</span><strong>{{ gameStats.adult||0 }}</strong></div><div class="metric-card" :class="{on:activeMetric==='mature'}" role="button" tabindex="0" @click="clickMetric('mature')" @keydown.enter="clickMetric('mature')"><span>成熟</span><strong>{{ gameStats.mature||0 }}</strong></div><div class="metric-card" :class="{on:activeMetric==='offers'}" role="button" tabindex="0" @click="clickMetric('offers')" @keydown.enter="clickMetric('offers')"><span>有报价</span><strong>{{ gameStats.withOffers||0 }}</strong></div><div class="metric-card" :class="{on:false}" role="button" tabindex="0" @click="clickMetric('deleted')" @keydown.enter="clickMetric('deleted')"><span>已删除</span><strong>{{ gameStats.deleted||0 }}</strong></div></div>
        <BulkBar :count="sel.games.count" :actions="gamesBulkActions" :running="bulkRunning" @run="(a)=>runBulk(a,sel.games,{refresh:refreshGames})" @clear="sel.games.clear()"/><div class="module-card table-card"><template v-if="!isMobile"><el-table ref="gamesTable" row-key="id" :data="games" v-loading="loading" stripe @selection-change="sel.games.onSelectionChange"><el-table-column type="selection" width="44"/><el-table-column label="游戏" min-width="250"><template #default="{row}"><div class="game-admin"><img v-if="row.steam_appid" :src="`/img/steam/${row.steam_appid}/capsule_sm_120`" @error="$event.target.style.display='none'"><div><strong>{{ row.name }}</strong><el-button link class="copy-name" title="复制游戏名" @click.stop="copyGameName(row)"><el-icon><CopyDocument /></el-icon></el-button><small>{{ row.name_en || (row.steam_appid ? `AppID ${row.steam_appid}` : '无 Steam AppID') }}</small></div></div></template></el-table-column><el-table-column label="平台" min-width="130"><template #default="{row}"><el-tag v-for="p in row.platform_names||[]" :key="p" size="small" class="tag-gap">{{ p }}</el-tag><span v-if="!row.platform_names?.length" class="muted">—</span></template></el-table-column><el-table-column label="Steam 价" width="105" align="right"><template #default="{row}">{{ price(row.steam_price) }}</template></el-table-column><el-table-column label="信息" width="100"><template #default="{row}"><el-tag :type="row.has_desc?'success':'info'" size="small">{{ row.has_desc?'有简介':'缺简介' }}</el-tag></template></el-table-column><el-table-column label="报价" prop="offer_count" width="72" align="right"/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.blocked?'danger':'success'" size="small">{{ row.blocked?'已禁用':'正常' }}</el-tag></template></el-table-column><el-table-column label="同步状态" width="105"><template #default="{row}"><el-tag :type="row.steam_status==='ok'?'success':row.steam_status==='region_locked'?'danger':row.steam_status==='coming_soon'?'warning':'info'" size="small">{{ steamStatusLabel(row) }}</el-tag></template></el-table-column><el-table-column label="分级" width="80"><template #default="{row}"><el-tag v-if="row.adult_flag" type="danger" size="small">成人</el-tag><el-tag v-else-if="row.mature_flag" type="warning" size="small">成熟</el-tag><span v-else class="muted">—</span></template></el-table-column><el-table-column label="链接" width="85" align="right"><template #default="{row}"><el-button v-if="row.link_count" link type="primary" @click="openGameLinks(row)">{{ row.link_count }} 个</el-button><span v-else class="muted">—</span></template></el-table-column><el-table-column label="操作" width="170" fixed="right"><template #default="{row}"><el-button v-if="row.steam_appid" link type="primary" @click="editGame(row)">编辑</el-button><el-button v-if="row.steam_appid" link @click="toggleGame(row)">{{ row.blocked?'启用':'禁用' }}</el-button><el-button link type="danger" @click="deleteGame(row)">删除</el-button></template></el-table-column></el-table></template><div v-else class="game-card-list"><div v-for="row in games" :key="row.id" class="admin-card"><div class="admin-card-pick"><el-checkbox :model-value="sel.games.has(row)" @change="sel.games.toggle(row)">选择</el-checkbox></div><div class="admin-card-main"><div class="game-admin"><img v-if="row.steam_appid" :src="`/img/steam/${row.steam_appid}/capsule_sm_120`" @error="$event.target.style.display='none'"><div><strong>{{ row.name }}</strong><el-button link class="copy-name" title="复制游戏名" @click.stop="copyGameName(row)"><el-icon><CopyDocument /></el-icon></el-button><small>{{ row.name_en || (row.steam_appid ? `AppID ${row.steam_appid}` : '无 Steam AppID') }}</small></div></div><div class="admin-card-tags"><el-tag v-for="p in row.platform_names||[]" :key="p" size="small" class="tag-gap">{{ p }}</el-tag><el-tag size="small" :type="row.has_desc?'success':'info'">{{ row.has_desc?'有简介':'缺简介' }}</el-tag><el-tag size="small" :type="row.blocked?'danger':'success'">{{ row.blocked?'已禁用':'正常' }}</el-tag><el-tag size="small" :type="row.steam_status==='ok'?'success':row.steam_status==='region_locked'?'danger':row.steam_status==='coming_soon'?'warning':'info'">{{ steamStatusLabel(row) }}</el-tag><el-tag v-if="row.adult_flag" size="small" type="danger">成人</el-tag><el-tag v-else-if="row.mature_flag" size="small" type="warning">成熟</el-tag></div></div><div class="admin-card-foot"><span>Steam {{ price(row.steam_price) }} · 报价 {{ row.offer_count }}<template v-if="row.link_count"> · <el-button link type="primary" @click="openGameLinks(row)">链接 {{ row.link_count }}</el-button></template></span><span><el-button v-if="row.steam_appid" link type="primary" @click="editGame(row)">编辑</el-button><el-button v-if="row.steam_appid" link @click="toggleGame(row)">{{ row.blocked?'启用':'禁用' }}</el-button><el-button link type="danger" @click="deleteGame(row)">删除</el-button></span></div></div></div><el-drawer v-model="linksDrawer.visible" :size="isMobile?'100%':'520px'" :class="isMobile?'mobile-full':''" :title="linksDrawer.game?`${linksDrawer.game.name||'游戏'} 的平台链接`:'平台链接'" append-to-body><template v-if="linksDrawer.game"><div class="links-drawer-head"><strong>{{ linksDrawer.game.name }}</strong><el-button link title="复制游戏名" @click="copyGameName(linksDrawer.game)"><el-icon><CopyDocument /></el-icon></el-button><small v-if="linksDrawer.game.steam_appid">AppID {{ linksDrawer.game.steam_appid }}</small><el-button v-if="linksDrawer.game.steam_appid" link title="复制 AppID" @click="copyGameName(linksDrawer.game,true)">复制 AppID</el-button></div><div v-loading="linksDrawer.loading" class="links-drawer-list"><div v-for="l in linksDrawer.links" :key="`${l.platform_code}|${l.region}|${l.buy_url}`" class="link-row"><div class="link-main"><strong>{{ l.platform_name }}</strong><span>{{ l.region }} · {{ price(l.price_cents) }}<small>{{ dateTime(l.last_seen_at) }}</small></span></div><a :href="l.buy_url" target="_blank" rel="noopener noreferrer"><el-button size="small" type="primary">打开</el-button></a></div><el-empty v-if="!linksDrawer.links.length" description="没有可用的平台链接"><a v-if="linksDrawer.game.steam_appid" :href="`https://store.steampowered.com/app/${linksDrawer.game.steam_appid}/`" target="_blank" rel="noopener noreferrer"><el-button size="small">去 Steam 商店页</el-button></a></el-empty></div></template></el-drawer>
          <div class="pager"><span>共 {{ gameTotal }} 款 · 第 {{ gamePage }}/{{ gamePages }} 页</span><el-pagination background layout="prev, pager, next, sizes" :total="gameTotal" :current-page="gamePage" :page-size="gamePageSize" :page-sizes="[20,50,100]" @current-change="loadGames" @size-change="changeGameSize"/></div>
        </div>
        <el-dialog v-model="gameDialog" title="编辑游戏" width="min(560px, 92vw)"><p class="muted">{{ activeGame?.name }} · AppID {{ activeGame?.steam_appid }}</p><el-form label-position="top"><el-form-item label="游戏简介"><el-input v-model="gameDescription" type="textarea" :rows="5" maxlength="10000" show-word-limit/></el-form-item><el-form-item><el-checkbox v-model="gameBlocked">在前台隐藏并停止常规展示</el-checkbox></el-form-item></el-form><template #footer><el-button @click="closeGameDialog">取消</el-button><el-button type="primary" :loading="saving" @click="saveGame">保存</el-button></template></el-dialog>
        <el-dialog v-model="mergeDialog" title="合并重复游戏" width="min(480px, 92vw)"><p class="muted">用于同一游戏被收录两次（不同 AppID）时人工合并；报价与历史会迁到目标游戏。</p><el-form label-position="top"><el-form-item label="源 AppID（被合并方，合并后删除）"><el-input v-model="mergeForm.from" type="number" placeholder="例如 440"/></el-form-item><el-form-item label="目标 AppID（保留方）"><el-input v-model="mergeForm.to" type="number" placeholder="例如 730"/></el-form-item></el-form><template #footer><el-button @click="mergeDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="mergeGames">合并</el-button></template></el-dialog>
      </template>
      <template v-else>
        <div class="notice-card"><strong>数据任务由服务器自动执行</strong><p>下表是调度计划与运行状态；需要立即执行时点「立即运行」（使用默认参数）。任务之间自动互斥，不会同时抢占 Steam 配额。价格刷新间隔可在「系统设置 → 数据源与采集」调整。</p></div>
        <div v-if="runningJob && backfillProgress" class="notice-card"><strong>任务实时进度：{{ TASK_META[runningJob]?.label||runningJob }}</strong><p>{{ backfillProgress.done }} / {{ backfillProgress.limit }}（{{ backfillProgress.percent }}%）· 速度 {{ backfillProgress.ratePerMin }} 款/分钟<template v-if="backfillProgress.ratePerMin>0 && backfillProgress.limit>backfillProgress.done"> · 预计剩余约 {{ Math.max(1, Math.round((backfillProgress.limit-backfillProgress.done)/backfillProgress.ratePerMin)) }} 分钟</template></p></div>
        <div class="module-card table-card"><el-alert v-if="syncWarnings.length" type="warning" :closable="false" class="task-warnings"><p v-for="w in syncWarnings" :key="w.name">任务 <strong>{{ w.name }}</strong> 缺失：{{ w.reason }}</p></el-alert><el-table :data="taskRows" v-loading="loading"><el-table-column prop="label" label="任务" min-width="110"/><el-table-column prop="freq" label="频率" width="90"/><el-table-column label="上次运行" min-width="155"><template #default="{row}">{{ row.lastRunAt ? dateTime(row.lastRunAt) : '—' }}</template></el-table-column><el-table-column label="下次运行" min-width="155"><template #default="{row}">{{ row.nextRunAt ? dateTime(row.nextRunAt) : '—' }}</template></el-table-column><el-table-column label="上次结果" width="95"><template #default="{row}"><el-tag v-if="row.lastResult==='ok'" type="success" size="small">成功</el-tag><el-tag v-else-if="row.lastResult==='failed'" type="danger" size="small">失败</el-tag><span v-else class="muted">—</span></template></el-table-column><el-table-column label="耗时" width="105" align="right"><template #default="{row}">{{ fmtDur(row.lastElapsedMs) }}</template></el-table-column><el-table-column label="失败原因" min-width="150" show-overflow-tooltip><template #default="{row}">{{ row.lastError||'—' }}</template></el-table-column><el-table-column label="状态" width="140"><template #default="{row}"><el-tag v-if="row.name === runningJob" type="primary" size="small">运行中</el-tag><el-tag v-else-if="row.waitingFor" type="info" size="small">等待 {{ row.waitingFor.occupiedBy }}</el-tag><el-tag v-else-if="row.openUntil" type="danger" size="small">熔断至 {{ dateTime(row.openUntil) }}</el-tag><el-tag v-else-if="row.failures" type="warning" size="small">失败 {{ row.failures }} 次</el-tag><span v-else class="muted">空闲</span></template></el-table-column><el-table-column label="操作" width="110"><template #default="{row}"><el-button link type="primary" :disabled="Boolean(runningJob)" @click="runTask(row.name)">立即运行</el-button></template></el-table-column></el-table></div>
        <div class="module-card task-state"><div><span class="eyebrow-small">当前任务</span><strong>{{ runningJob ? (TASK_META[runningJob]?.label || runningJob) : '空闲' }}</strong></div><div v-if="syncStatus?.run" class="muted">{{ syncStatus.run.mode }} · {{ dateTime(syncStatus.run.startedAt) }}</div><pre v-if="syncStatus?.output">{{ syncStatus.output }}</pre><div v-if="runningJob" class="task-actions"><el-button type="danger" plain @click="stopCurrent">停止</el-button></div></div>
      </template>
    </template>

    <!-- 访问与安全 -->
    <template v-else-if="section==='visitors'">
      <div class="module-tabs"><button v-for="tab in visitorTabs" :key="tab.value" :class="{on:visitorView===tab.value}" @click="visitorView=tab.value;loadVisitorView()">{{ tab.label }}</button></div>
      <template v-if="visitorView==='visits'">
        <div class="metric-grid"><div class="metric-card"><span>今日访问</span><strong>{{ visitorSummary.today_visits||0 }}</strong></div><div class="metric-card"><span>今日独立 IP</span><strong>{{ visitorSummary.today_ips||0 }}</strong></div><div class="metric-card"><span>今日拦截</span><strong>{{ visitorSummary.today_blocked||0 }}</strong></div><div class="metric-card"><span>黑名单</span><strong>{{ visitorSummary.blocked_count||0 }}</strong></div></div>
        <div class="module-card filterbar"><el-select v-model="visitorFilter" @change="loadVisitors(1)"><el-option label="正常访问" value="visits"/><el-option label="已拦截" value="blocked"/><el-option label="全部记录" value="all"/></el-select><el-input v-model="visitorIp" clearable placeholder="按 IP 筛选" @keyup.enter="loadVisitors(1)"/><el-input v-model="visitorPath" clearable placeholder="按路径筛选" @keyup.enter="loadVisitors(1)"/><el-button @click="loadVisitors(1)">查询</el-button></div>
        <BulkBar :count="sel.visitors.count" :actions="visitorsBulkActions" :running="bulkRunning" @run="(a)=>runBulk(a,sel.visitors,{refresh:()=>loadVisitors(visitorPage)})" @clear="sel.visitors.clear()"/><div class="module-card table-card"><template v-if="!isMobile"><el-table ref="visitorsTable" :data="visitors" v-loading="loading" stripe @selection-change="sel.visitors.onSelectionChange"><el-table-column type="selection" width="44"/><el-table-column label="IP" min-width="155"><template #default="{row}"><span class="mono">{{ row.ip }}</span><small v-if="row.remote_ip && row.remote_ip!==row.ip">直连 {{ row.remote_ip }}</small></template></el-table-column><el-table-column prop="region" label="地区" width="100"/><el-table-column label="路径" min-width="220" show-overflow-tooltip><template #default="{row}">{{ row.path }}<small v-if="row.block_reason">{{ row.block_reason }}</small></template></el-table-column><el-table-column label="结果" width="100"><template #default="{row}"><el-tag v-if="row.blocked" type="danger" size="small">拦截 {{ row.status }}</el-tag><el-tag v-else-if="row.status>=400" type="warning" size="small">{{ row.status }}</el-tag><span v-else>{{ row.status||'—' }}</span></template></el-table-column><el-table-column label="时间" min-width="160"><template #default="{row}">{{ dateTime(row.created_at) }}</template></el-table-column><el-table-column label="操作" width="140"><template #default="{row}"><el-button link type="danger" @click="banIp(row.ip)">封禁 IP</el-button><el-button link @click="addWhitelist(row.ip)">信任</el-button></template></el-table-column></el-table></template><div v-else class="game-card-list"><div v-for="row in visitors" :key="row.id" class="admin-card"><div class="admin-card-pick"><el-checkbox :model-value="sel.visitors.has(row)" @change="sel.visitors.toggle(row)">选择</el-checkbox></div><div class="admin-card-main"><strong class="mono">{{ row.ip }}</strong><small v-if="row.remote_ip && row.remote_ip!==row.ip">直连 {{ row.remote_ip }}</small><span class="muted">{{ row.region||'—' }}</span><p class="admin-card-path">{{ row.path }}<small v-if="row.block_reason"> · {{ row.block_reason }}</small></p></div><div class="admin-card-foot"><span><el-tag v-if="row.blocked" type="danger" size="small">拦截 {{ row.status }}</el-tag><el-tag v-else-if="row.status>=400" type="warning" size="small">{{ row.status }}</el-tag><span v-else>{{ row.status||'—' }}</span> · {{ dateTime(row.created_at) }}</span><span><el-button link type="danger" @click="banIp(row.ip)">封禁 IP</el-button><el-button link @click="addWhitelist(row.ip)">信任</el-button></span></div></div></div><div class="pager"><span>共 {{ visitorTotal }} 条</span><PaginationBar v-model:page="visitorPage" v-model:page-size="visitorPageSize" :total="visitorTotal" @change="loadVisitors"/></div></div>
      </template>
      <template v-else-if="visitorView==='review'">
        <div class="notice-card"><strong>异常请求由管理员审核</strong><p>系统记录异常但不自动永久封禁；审核后可封 IP、封设备或忽略。白名单可保护自己的管理出口 IP。封禁发生时该 IP 的旧待审会标记为 auto_banned 永久退出待审（「全部」视图可查）；封禁期间产生的新异常仍会以「待审」出现（状态列可据此判断是否已处理）。</p></div>
        <div class="module-card table-card"><div class="card-heading padded"><div><h3>待审列表</h3><p>auto_banned = 封禁发生时自动退出待审的旧记录</p></div><el-select v-model="reviewStatus" style="width:130px" @change="loadReviews"><el-option label="只看待审" value="pending"/><el-option label="全部（审计）" value="all"/></el-select></div><BulkBar :count="sel.reviews.count" :actions="reviewsBulkActions" :running="bulkRunning" @run="(a)=>runBulk(a,sel.reviews,{refresh:loadReviews})" @clear="sel.reviews.clear()"/><template v-if="!isMobile"><el-table ref="reviewsTable" row-key="id" :data="pagedReviews" v-loading="loading" stripe @selection-change="sel.reviews.onSelectionChange"><el-table-column type="selection" width="44" :selectable="(row)=>row.status==='pending'"/><el-table-column label="最近出现" min-width="155"><template #default="{row}">{{ dateTime(row.last_seen) }}</template></el-table-column><el-table-column prop="ip" label="IP" width="140"/><el-table-column label="规则" min-width="130"><template #default="{row}">{{ row.rule }}</template></el-table-column><el-table-column prop="hits" label="次数" width="75" align="right"/><el-table-column label="状态" width="110"><template #default="{row}"><el-tag v-if="row.status==='pending'" type="success" size="small">待审</el-tag><el-tag v-else-if="row.status==='approved'" type="danger" size="small" :title="reviewStatusHint(row)">已封禁</el-tag><el-tag v-else-if="row.status==='rejected'" type="info" size="small" :title="reviewStatusHint(row)">已忽略</el-tag><el-tag v-else type="info" size="small" :title="reviewStatusHint(row)">自动退出</el-tag></template></el-table-column><el-table-column label="请求" min-width="180" show-overflow-tooltip><template #default="{row}">{{ row.path||row.detail }}</template></el-table-column><el-table-column label="操作" width="200"><template #default="{row}"><el-button v-if="row.status==='pending'" link type="danger" @click="reviewAction(row,'ip')">封 IP</el-button><el-button v-if="row.status==='pending' && row.fingerprint" link type="danger" @click="reviewAction(row,'device')">封设备</el-button><el-button v-if="row.status==='pending'" link @click="ignoreReview(row)">忽略</el-button></template></el-table-column></el-table></template><div v-else class="game-card-list"><div v-for="row in pagedReviews" :key="row.id" class="admin-card"><div class="admin-card-pick"><el-checkbox :model-value="sel.reviews.has(row)" :disabled="row.status!=='pending'" @change="sel.reviews.toggle(row)">选择</el-checkbox></div><div class="admin-card-main"><strong class="mono">{{ row.ip }}</strong><small>{{ dateTime(row.last_seen) }} · 命中 {{ row.hits }} 次</small><span class="muted">{{ row.rule }}</span><el-tag v-if="row.status==='pending'" type="success" size="small">待审</el-tag><el-tag v-else-if="row.status==='approved'" type="danger" size="small">已封禁</el-tag><el-tag v-else-if="row.status==='rejected'" type="info" size="small">已忽略</el-tag><el-tag v-else type="info" size="small">自动退出</el-tag><p class="admin-card-path">{{ row.path||row.detail }}</p></div><div class="admin-card-foot"><span></span><span><el-button v-if="row.status==='pending'" link type="danger" @click="reviewAction(row,'ip')">封 IP</el-button><el-button v-if="row.status==='pending' && row.fingerprint" link type="danger" @click="reviewAction(row,'device')">封设备</el-button><el-button v-if="row.status==='pending'" link @click="ignoreReview(row)">忽略</el-button></span></div></div></div><PaginationBar v-model:page="reviewsPage" v-model:page-size="reviewsPageSize" :total="reviews.length"/></div>
      </template>
      <template v-else-if="visitorView==='devices'">
        <div class="notice-card"><strong>设备封禁按指纹生效</strong><p>换 IP 也会命中；白名单 IP 不受影响。审核弹窗「封设备」产生的封禁同样在这里管理。解封后该设备仍会出现在「最近设备」里（历史记录不删）。</p></div>
        <div class="module-card table-card"><div class="card-heading padded"><div><h3>最近设备</h3><p>按设备指纹去重，最多 100 条</p></div><el-button text @click="loadDevices">刷新</el-button></div><BulkBar :count="sel.devices.count" :actions="devicesBulkActions" :running="bulkRunning" @run="openBulkDeviceBan" @clear="sel.devices.clear()"/><template v-if="!isMobile"><el-table ref="devicesTable" row-key="fingerprint" :data="pagedDevices" v-loading="loading" stripe @selection-change="sel.devices.onSelectionChange"><el-table-column type="selection" width="44" :selectable="(row)=>Boolean(row.fingerprint)"/><el-table-column label="最近出现" min-width="155"><template #default="{row}">{{ dateTime(row.created_at) }}</template></el-table-column><el-table-column prop="ip" label="IP" width="135"/><el-table-column label="设备 ID" min-width="130" show-overflow-tooltip><template #default="{row}"><span class="mono">{{ row.device_id||'—' }}</span></template></el-table-column><el-table-column label="指纹" min-width="150"><template #default="{row}"><span class="mono" :title="row.fingerprint">{{ String(row.fingerprint||'').slice(0,12) }}…</span></template></el-table-column><el-table-column label="UA" min-width="200" show-overflow-tooltip><template #default="{row}"><span class="muted">{{ String(row.user_agent||'').slice(0,60) }}</span></template></el-table-column><el-table-column label="操作" width="100" fixed="right"><template #default="{row}"><el-button v-if="row.fingerprint" link type="danger" @click="openDeviceBan(row)">封禁</el-button></template></el-table-column></el-table></template><div v-else class="game-card-list"><div v-for="row in pagedDevices" :key="row.fingerprint||row.device_id||row.ip" class="admin-card"><div class="admin-card-pick"><el-checkbox :model-value="sel.devices.has(row)" :disabled="!row.fingerprint" @change="sel.devices.toggle(row)">选择</el-checkbox></div><div class="admin-card-main"><strong class="mono">{{ row.device_id||'—' }}</strong><small>{{ row.ip }} · {{ dateTime(row.created_at) }}</small><span class="mono muted">{{ String(row.fingerprint||'').slice(0,12) }}…</span><p class="admin-card-path">{{ String(row.user_agent||'').slice(0,60) }}</p></div><div class="admin-card-foot"><span></span><span><el-button v-if="row.fingerprint" link type="danger" @click="openDeviceBan(row)">封禁</el-button></span></div></div></div><PaginationBar v-model:page="devicesPage" v-model:page-size="devicesPageSize" :total="devices.length"/></div>
        <div class="module-card table-card"><div class="card-heading padded"><div><h3>已封设备</h3><p>封禁至为空 = 永久</p></div><el-button text @click="loadDevices">刷新</el-button></div><BulkBar :count="sel.deviceBans.count" :actions="deviceBansBulkActions" :running="bulkRunning" @run="(a)=>runBulk(a,sel.deviceBans,{refresh:loadDevices})" @clear="sel.deviceBans.clear()"/><template v-if="!isMobile"><el-table ref="deviceBansTable" row-key="fingerprint" :data="pagedDeviceBans" v-loading="loading" stripe @selection-change="sel.deviceBans.onSelectionChange"><el-table-column type="selection" width="44"/><el-table-column label="指纹" min-width="150"><template #default="{row}"><span class="mono" :title="row.fingerprint">{{ String(row.fingerprint||'').slice(0,12) }}…</span></template></el-table-column><el-table-column label="设备 ID" min-width="130" show-overflow-tooltip><template #default="{row}"><span class="mono">{{ row.device_id||'—' }}</span></template></el-table-column><el-table-column label="封禁至" width="170"><template #default="{row}">{{ row.until ? dateTime(row.until) : '永久' }}</template></el-table-column><el-table-column label="备注" min-width="160" show-overflow-tooltip><template #default="{row}">{{ row.note||'—' }}</template></el-table-column><el-table-column label="操作" width="100" fixed="right"><template #default="{row}"><el-button link type="primary" @click="unbanDevice(row)">解封</el-button></template></el-table-column></el-table></template><div v-else class="game-card-list"><div v-for="row in pagedDeviceBans" :key="row.fingerprint||row.device_id" class="admin-card"><div class="admin-card-pick"><el-checkbox :model-value="sel.deviceBans.has(row)" @change="sel.deviceBans.toggle(row)">选择</el-checkbox></div><div class="admin-card-main"><strong class="mono">{{ String(row.fingerprint||'').slice(0,12) }}…</strong><small>{{ row.device_id||'—' }} · 封禁至 {{ row.until ? dateTime(row.until) : '永久' }}</small><p class="admin-card-path">{{ row.note||'—' }}</p></div><div class="admin-card-foot"><span></span><span><el-button link type="primary" @click="unbanDevice(row)">解封</el-button></span></div></div></div><PaginationBar v-model:page="deviceBansPage" v-model:page-size="deviceBansPageSize" :total="deviceBans.length"/></div>
        <el-dialog v-model="deviceBanDialog.visible" title="封禁设备" width="min(400px, 92vw)"><p class="muted">指纹 {{ String(deviceBanDialog.row?.fingerprint||'').slice(0,12) }}…；该设备所有请求将被拒绝（白名单 IP 除外）。</p><el-radio-group v-model="deviceBanDialog.duration"><el-radio :value="10">10 分钟</el-radio><el-radio :value="60">1 小时</el-radio><el-radio :value="1440">1 天</el-radio><el-radio :value="'permanent'">永久</el-radio></el-radio-group><template #footer><el-button @click="deviceBanDialog.visible=false">取消</el-button><el-button type="danger" :loading="saving" @click="banDevice">确认封禁</el-button></template></el-dialog>
      </template>
      <template v-else>
        <div class="security-grid"><div class="module-card"><div class="card-heading"><div><h3>IP 黑名单</h3><p>封禁后该 IP 无法访问站点</p></div><el-button text @click="loadSecurity">刷新</el-button></div><div class="inline-form"><el-input v-model="newBlockIp" placeholder="IP 或 CIDR" @keyup.enter="addBlacklist"/><el-input v-model="newBlockNote" placeholder="备注（可选）" @keyup.enter="addBlacklist"/><el-button type="danger" @click="addBlacklist">封禁</el-button></div><BulkBar :count="sel.blacklist.count" :actions="blacklistBulkActions" :running="bulkRunning" @run="(a)=>runBulk(a,sel.blacklist,{refresh:loadSecurity})" @clear="sel.blacklist.clear()"/><template v-if="!isMobile"><el-table ref="blacklistTable" row-key="ip" :data="pagedBlacklist" size="small" @selection-change="sel.blacklist.onSelectionChange"><el-table-column type="selection" width="44"/><el-table-column prop="ip" label="IP / CIDR"/><el-table-column prop="note" label="备注"/><el-table-column label="操作" width="80"><template #default="{row}"><el-button link type="primary" @click="removeBlacklist(row.ip)">解封</el-button></template></el-table-column></el-table></template><div v-else class="game-card-list"><div v-for="row in pagedBlacklist" :key="row.ip" class="admin-card"><div class="admin-card-pick"><el-checkbox :model-value="sel.blacklist.has(row)" @change="sel.blacklist.toggle(row)">选择</el-checkbox></div><div class="admin-card-main"><strong class="mono">{{ row.ip }}</strong><p class="admin-card-path">{{ row.note||'—' }}</p></div><div class="admin-card-foot"><span></span><span><el-button link type="primary" @click="removeBlacklist(row.ip)">解封</el-button></span></div></div></div><PaginationBar v-model:page="blacklistPage" v-model:page-size="blacklistPageSize" :total="blacklist.length"/></div>
        <div class="module-card"><div class="card-heading"><div><h3>IP 白名单</h3><p>白名单 IP 不受自动频率封禁</p></div><el-button text @click="loadSecurity">刷新</el-button></div><div class="inline-form"><el-input v-model="newAllowIp" placeholder="IP 或 CIDR" @keyup.enter="addWhitelist(null)"/><el-input v-model="newAllowNote" placeholder="备注（可选）" @keyup.enter="addWhitelist(null)"/><el-button type="primary" @click="addWhitelist(null)">信任</el-button></div><BulkBar :count="sel.whitelist.count" :actions="whitelistBulkActions" :running="bulkRunning" @run="(a)=>runBulk(a,sel.whitelist,{refresh:loadSecurity})" @clear="sel.whitelist.clear()"/><template v-if="!isMobile"><el-table ref="whitelistTable" row-key="ip" :data="pagedWhitelist" size="small" @selection-change="sel.whitelist.onSelectionChange"><el-table-column type="selection" width="44"/><el-table-column prop="ip" label="IP / CIDR"/><el-table-column prop="note" label="备注"/><el-table-column label="操作" width="80"><template #default="{row}"><el-button link type="danger" @click="removeWhitelist(row.ip)">移除</el-button></template></el-table-column></el-table></template><div v-else class="game-card-list"><div v-for="row in pagedWhitelist" :key="row.ip" class="admin-card"><div class="admin-card-pick"><el-checkbox :model-value="sel.whitelist.has(row)" @change="sel.whitelist.toggle(row)">选择</el-checkbox></div><div class="admin-card-main"><strong class="mono">{{ row.ip }}</strong><p class="admin-card-path">{{ row.note||'—' }}</p></div><div class="admin-card-foot"><span></span><span><el-button link type="danger" @click="removeWhitelist(row.ip)">移除</el-button></span></div></div></div><PaginationBar v-model:page="whitelistPage" v-model:page-size="whitelistPageSize" :total="whitelist.length"/></div></div>
        <div class="module-card table-card security-events"><div class="card-heading"><div><h3>自动封禁记录</h3><p>临时频率限制或路径规则命中的地址</p></div></div><BulkBar :count="sel.abuse.count" :actions="abuseBulkActions" :running="bulkRunning" @run="(a)=>runBulk(a,sel.abuse,{refresh:loadSecurity})" @clear="sel.abuse.clear()"/><template v-if="!isMobile"><el-table ref="abuseTable" row-key="ip" :data="pagedAbuse" size="small" @selection-change="sel.abuse.onSelectionChange"><el-table-column type="selection" width="44"/><el-table-column prop="ip" label="IP"/><el-table-column prop="strikes" label="频率命中"/><el-table-column prop="path_strikes" label="路径命中"/><el-table-column prop="ban_source" label="来源"/><el-table-column label="封禁至"><template #default="{row}">{{ row.banned_until?dateTime(row.banned_until):'—' }}</template></el-table-column><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" @click="unbanAbuse(row.ip)">解封</el-button></template></el-table-column></el-table></template><div v-else class="game-card-list"><div v-for="row in pagedAbuse" :key="row.ip" class="admin-card"><div class="admin-card-pick"><el-checkbox :model-value="sel.abuse.has(row)" @change="sel.abuse.toggle(row)">选择</el-checkbox></div><div class="admin-card-main"><strong class="mono">{{ row.ip }}</strong><small>频率命中 {{ row.strikes }} · 路径命中 {{ row.path_strikes }} · {{ row.ban_source||'—' }}</small><span class="muted">封禁至 {{ row.banned_until?dateTime(row.banned_until):'—' }}</span></div><div class="admin-card-foot"><span></span><span><el-button link type="primary" @click="unbanAbuse(row.ip)">解封</el-button></span></div></div></div><PaginationBar v-model:page="abusePage" v-model:page-size="abusePageSize" :total="abuse.length"/></div>
      </template>
    </template>

    <!-- 公告 -->
    <template v-else-if="section==='announcements'">
      <div class="module-card announcement-form"><div class="card-heading"><div><h3>{{ announcement.id?'编辑通知':'发布站点通知' }}</h3><p>可设置显示级别和生效时间；不填时间表示立即生效且不过期。</p></div><el-button v-if="announcement.id" text @click="resetAnnouncement">取消编辑</el-button></div><el-form label-position="top"><div class="form-row"><el-form-item label="标题" class="grow"><el-input v-model="announcement.title" maxlength="120" show-word-limit placeholder="例如：价格同步维护通知"/></el-form-item><el-form-item label="级别"><el-select v-model="announcement.level"><el-option label="普通通知" value="info"/><el-option label="提醒" value="warning"/><el-option label="重要" value="critical"/></el-select></el-form-item><el-form-item label="状态"><el-switch v-model="announcement.active" active-text="启用" inactive-text="停用"/></el-form-item></div><el-form-item label="正文"><el-input v-model="announcement.body" type="textarea" :rows="3" maxlength="3000" show-word-limit placeholder="填写用户需要知道的内容"/></el-form-item><div class="form-row"><el-form-item label="开始时间"><el-date-picker v-model="announcement.startsAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" placeholder="立即生效"/></el-form-item><el-form-item label="结束时间"><el-date-picker v-model="announcement.endsAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" placeholder="永不过期"/></el-form-item><el-button type="primary" :loading="saving" @click="saveAnnouncement">{{ announcement.id?'保存修改':'发布通知' }}</el-button></div></el-form></div>
      <BulkBar :count="sel.announcements.count" :actions="announcementsBulkActions" :running="bulkRunning" @run="(a)=>runBulk(a,sel.announcements,{refresh:loadAnnouncements})" @clear="sel.announcements.clear()"/><div class="announcement-list"><article v-for="a in pagedAnnouncements" :key="a.id" class="module-card announcement-item"><el-checkbox class="announcement-pick" :model-value="sel.announcements.has(a)" @change="sel.announcements.toggle(a)"/><div class="announcement-badge" :class="a.level">{{ levelLabel(a.level) }}</div><div class="announcement-copy"><div class="card-heading"><h3>{{ a.title }}</h3><el-tag :type="a.active?'success':'info'" size="small">{{ a.active?'启用':'停用' }}</el-tag></div><p>{{ a.body }}</p><small>{{ a.starts_at?dateTime(a.starts_at):'立即生效' }} — {{ a.ends_at?dateTime(a.ends_at):'长期有效' }}</small></div><div class="item-actions"><el-button @click="editAnnouncement(a)">编辑</el-button><el-button type="danger" plain @click="removeAnnouncement(a.id)">删除</el-button></div></article><el-empty v-if="!announcements.length" description="还没有站点通知"/></div>
    </template>

    <!-- 设置 -->
    <template v-else-if="section==='settings'">
      <div class="settings-toolbar"><el-input v-model="settingQuery" clearable placeholder="搜索设置项，例如 Steam、代理、SMTP" @keyup.enter="onSettingsEnter"/><el-button v-if="theme.storedMode()" text @click="resetTheme">跟随系统</el-button><el-button @click="loadSettings">重新加载</el-button><el-button type="primary" :loading="saving" @click="saveSettings">保存设置</el-button></div>
      <div class="settings-meta">版本 {{ settingsSchema?.version||'—' }} · 配置修订 {{ settingsSchema?.revision||0 }} · 保存后调度器约 15 秒内生效 <span v-if="settingsDirty" class="dirty-dot">未保存的修改</span></div>
      <el-empty v-if="!filteredGroups.length && settingsSchema" description="没有匹配的设置项"/>
