async function submitAnnouncement(){if(!announcement.title.trim()||!announcement.body.trim())throw new Error('标题和正文都要填写');const payload={title:announcement.title.trim(),body:announcement.body.trim(),level:announcement.level,active:announcement.active,startsAt:announcement.startsAt?new Date(announcement.startsAt).toISOString():null,endsAt:announcement.endsAt?new Date(announcement.endsAt).toISOString():null};await api(announcement.id?`/api/admin/announcements/${announcement.id}`:'/api/admin/announcements',json(announcement.id?'PATCH':'POST',payload));}
async function saveAnnouncement(){await run(async()=>{await submitAnnouncement();ElMessage.success(announcement.id?'通知已更新':'通知已发布');resetAnnouncement();await loadAnnouncements();});}
