function fieldsByGroup(groupId){const q=settingQuery.value.trim().toLocaleLowerCase();return (settingsSchema.value?.fields||[]).filter(f=>f.group===groupId&&!isMailSettingKey(f.key)&&(!q||`${f.label} ${f.key} ${f.help||''}`.toLocaleLowerCase().includes(q)));}
// 设置搜索按 Enter：有未保存修改时先提醒；没有匹配项给出提示；然后重新加载设置定义
function onSettingsEnter(){if(settingsDirty.value){ElMessage.warning('有未保存的修改，先保存再重新加载');return;}const q=settingQuery.value.trim().toLocaleLowerCase();if(q&&!(settingsSchema.value?.fields||[]).some(f=>`${f.label} ${f.key} ${f.help||''}`.toLocaleLowerCase().includes(q)))ElMessage.warning('没有匹配的设置项');loadSettings();}
const filteredGroups=computed(()=>{const groups=settingsSchema.value?.groups||[];return groups.filter(g=>fieldsByGroup(g.id).length);});
function visibleSettingCount(id){return fieldsByGroup(id).length;}
function sourceLabel(src){return ({database:'数据库',env:'环境变量',default:'默认值'})[src]||src||'默认值';}
function settingId(key){return `setting-${String(key).replace(/[^a-zA-Z0-9_-]/g,'-')}`;}
function secretPlaceholder(key){return settingsSchema.value?.secrets?.[key]?.hasValue?'已设置，留空保持原值':'尚未设置';}
async function loadSettings(){loading.value=true;try{const d=await api('/api/admin/settings');settingsSchema.value=d;for(const key of Object.keys(settingValues))delete settingValues[key];for(const field of d.fields||[]){settingValues[field.key]=field.type==='secret'?'':d.values?.[field.key]??field.default??(field.type==='bool'?false:'');}for(const key of Object.keys(clearSecrets))delete clearSecrets[key];expandedSettings.value=(d.groups||[]).slice(0,1).map(g=>g.id);settingsDirty.value=false;}catch(e){notifyError(e);}finally{loading.value=false;}}
async function revealSecret(key){try{const d=await api(`/api/admin/settings/value?key=${encodeURIComponent(key)}`);settingValues[key]=d.value??'';ElMessage.info('密钥已载入输入框；保存会保留该值');}catch(e){notifyError(e);}}
// AM-2（docs/PROXY-POOL.md §5）：Steam 代理池列表编辑器 + 健康状态表。
// 保存：非空行按顺序 join('\n') 提交 network.steamProxy，清空传 null；前端先做 http/https 与 ≤10 校验，服务端兜底。
// 健康表：状态 正常/冷却中(倒计时)/未知；「刷新」+ 网络分组展开且页面可见时每 10 秒自动刷新；保存后立即刷新一次。
const proxyList=ref([]),proxyEditing=ref(false),proxyRevealLoading=ref(false),proxyHealth=ref({proxies:[],lastGood:null,updatedAt:null}),healthNow=ref(Date.now());
let proxyTimer=null,proxyTick=0;
async function revealProxyList(){proxyRevealLoading.value=true;try{const d=await api('/api/admin/settings/value?key=network.steamProxy');proxyList.value=String(d.value??'').split(/\r?\n/).filter(Boolean).map(v=>({value:v}));proxyEditing.value=true;settingsDirty.value=true;}catch(e){notifyError(e);}finally{proxyRevealLoading.value=false;}}
function addProxy(){if(proxyList.value.length>=10){ElMessage.warning('Steam 代理池最多 10 条');return;}proxyList.value.push({value:''});settingsDirty.value=true;}
function removeProxy(i){proxyList.value.splice(i,1);settingsDirty.value=true;}
function moveProxy(i,dir){const j=i+dir;if(j<0||j>=proxyList.value.length)return;const arr=proxyList.value;[arr[i],arr[j]]=[arr[j],arr[i]];settingsDirty.value=true;}
function clearProxyList(){proxyList.value=[];settingsDirty.value=true;}
function proxyStateType(row){return row.state==='ok'?'success':row.state==='cooldown'?'warning':'info';}
function proxyStateText(row){if(row.state==='ok')return '正常';if(row.state==='cooldown'){const left=Math.max(0,(Date.parse(row.downUntil||'')-healthNow.value)/1000);return `冷却中 ${String(Math.floor(left/60)).padStart(2,'0')}:${String(Math.floor(left%60)).padStart(2,'0')}`;}return '未知';}
async function loadProxyHealth(){try{const d=await api('/api/admin/proxies');proxyHealth.value=d;}catch{/* 健康接口失败不影响设置页其它功能 */}}
function startProxyTimer(){if(proxyTimer)return;proxyTimer=setInterval(()=>{proxyTick+=1;healthNow.value=Date.now();const active=props.section==='settings'&&!document.hidden&&(expandedSettings.value||[]).includes('network');if(active&&proxyTick%10===0)loadProxyHealth();},1000);}
async function submitSettings(){const values={};for(const f of settingsSchema.value?.fields||[]){if(isMailSettingKey(f.key))continue;if(f.key==='network.steamProxy'&&proxyEditing.value){const lines=proxyList.value.map(r=>String(r.value??'').trim()).filter(Boolean);for(let i=0;i<lines.length;i+=1){if(!/^https?:\/\//i.test(lines[i]))throw new Error(`第 ${i+1} 行不是合法的 http/https 代理`);}if(lines.length>10)throw new Error('Steam 代理池最多 10 条');values[f.key]=lines.length?lines.join('\n'):null;continue;}const v=settingValues[f.key];if(f.type==='secret'){if(clearSecrets[f.key])values[f.key]=null;else if(String(v??'').trim()!=='')values[f.key]=v;}else if(f.type==='int'){values[f.key]=v===''||v==null?null:Number(v);}else if(f.type==='bool')values[f.key]=Boolean(v);else values[f.key]=v;}const d=await api('/api/admin/settings',json('POST',{values}));settingsSchema.value=d;for(const f of d.fields||[]){if(f.type==='secret')settingValues[f.key]='';else settingValues[f.key]=d.values?.[f.key]??f.default??'';}settingsDirty.value=false;return d;}
async function saveSettings(){await run(async()=>{const d=await submitSettings();ElMessage.success(`已保存 ${d.keys?.length||0} 项设置`);loadProxyHealth();});}
watch(settingQuery,()=>{if(settingQuery.value.trim())expandedSettings.value=(settingsSchema.value?.groups||[]).map(g=>g.id);});
// 翻页清空选择（决策：常规列表只支持本页勾选）。这些表是客户端分页，翻页不会走 load 函数，
// 所以单独 watch 页码；游戏目录 / 访问明细是服务端分页，已在 load 里清空。
watch(reviewsPage,()=>sel.reviews.clear());watch(blacklistPage,()=>sel.blacklist.clear());watch(whitelistPage,()=>sel.whitelist.clear());watch(abusePage,()=>sel.abuse.clear());watch(devicesPage,()=>sel.devices.clear());watch(deviceBansPage,()=>sel.deviceBans.clear());watch(announcementsPage,()=>sel.announcements.clear());
watch(gameView,(view)=>{if(view==='tasks')loadSyncStatus();else loadGames(1);});

const priceMetrics=computed(()=>[{label:'降价',value:priceReport.value.drops||0,tone:'metric-red'},{label:'涨价',value:priceReport.value.rises||0,tone:''},{label:'新史低',value:priceReport.value.newLows||0,tone:'metric-green'},{label:'价格变化',value:priceReport.value.changed||0,tone:''}]);
const priceChanges=computed(()=>[...(priceReport.value.topDrops||[]),...(priceReport.value.topRises||[])]);
const viewRows=computed(()=>{const rows=views.value.slice();if(!aggregateViews.value)return rows;const map=new Map();for(const v of rows){const key=v.name||v.path;const current=map.get(key)||{name:v.name,path:'多个页面',views:0,last_at:v.last_at};current.views+=v.views;if(v.last_at>current.last_at)current.last_at=v.last_at;map.set(key,current);}return [...map.values()].sort((a,b)=>b.views-a.views);});
const imageMb=computed(()=>((imageStats.value.bytes||0)/1024/1024).toFixed(1));
async function loadStats(){loading.value=true;try{const [r,v,i,b]=await Promise.all([api('/api/admin/reports/price?hours=24&limit=100&days=7'),api('/api/admin/views?limit=500'),api('/api/admin/images'),api('/api/admin/backups')]);priceReport.value=r.report||{};daily.value=r.daily||[];views.value=v.views||[];imageStats.value=i.images||{};backups.value=b.backups||[];}catch(e){notifyError(e);}finally{loading.value=false;}}
async function createBackup(){await run(async()=>{const d=await api('/api/admin/backup',json('POST',{}));backups.value=d.backups||backups.value;ElMessage.success(`备份完成：${d.result?.rows||0} 行`);});}

async function loadSyncStatus(){try{syncStatus.value=await api('/api/admin/sync/status');if(syncStatus.value?.running){try{const d=await api('/api/admin/backfill/status');backfillProgress.value=d.progress||null;}catch{/* 忽略 */}}else backfillProgress.value=null;}catch(e){notifyError(e);}}
async function runTask(name){await run(async()=>{if(name==='steam-prices'||name==='catalog'){await api('/api/admin/sync',json('POST',{mode:name}));}else{await api(`/api/admin/${name}`,json('POST',{}));}ElMessage.success('任务已提交到服务器');await loadSyncStatus();});}
async function stopCurrent(){await run(async()=>{const mode=syncStatus.value?.run?.mode||'';const path=mode==='rename'?'/api/admin/rename/stop':mode==='heat'?'/api/admin/heat/stop':'/api/admin/backfill/stop';await api(path,json('POST',{}));ElMessage.success('已请求停止');await loadSyncStatus();});}

watch(()=>props.section,(section)=>{if(section==='games')loadGames(1);else if(section==='visitors')loadVisitorView();else if(section==='announcements')loadAnnouncements();else if(section==='settings')loadSettings();else if(section==='stats')loadStats();else if(section==='bulk-ops')loadBulkOps();});
// AN 批（docs/UNSAVED-GUARD.md §4.4）：本组件注册三个编辑面——系统设置 / 站点通知 / 编辑游戏
const unregisterUnsaved=[];
onMounted(()=>{if(props.section==='games')loadGames(1);else if(props.section==='visitors')loadVisitorView();else if(props.section==='announcements')loadAnnouncements();else if(props.section==='settings'){loadSettings();loadProxyHealth();}else if(props.section==='stats')loadStats();else if(props.section==='bulk-ops')loadBulkOps();startProxyTimer();snapshotAnnouncement();unregisterUnsaved.push(registerUnsavedSource({id:'settings',label:'系统设置',isDirty:()=>settingsDirty.value,save:submitSettings}),registerUnsavedSource({id:'announcement',label:'站点通知',isDirty:announcementDirty,save:submitAnnouncement}),registerUnsavedSource({id:'edit-game',label:'编辑游戏',isDirty:gameDirty,save:submitGameSave}));if(window.matchMedia){const mq=window.matchMedia('(max-width: 720px)');const on=()=>isMobile.value=mq.matches;mq.addEventListener?mq.addEventListener('change',on):mq.addListener(on);}});
const statusTimer=setInterval(()=>{if(props.section==='games'&&gameView.value==='tasks')loadSyncStatus();},8000);
onBeforeUnmount(()=>{clearInterval(statusTimer);if(proxyTimer){clearInterval(proxyTimer);proxyTimer=null;}unregisterUnsaved.forEach((fn)=>fn());if(mobileQuery){if(mobileQuery.removeEventListener)mobileQuery.removeEventListener('change',onMobileChange);else mobileQuery.removeListener(onMobileChange);}});
if(mobileQuery){if(mobileQuery.addEventListener)mobileQuery.addEventListener('change',onMobileChange);else mobileQuery.addListener(onMobileChange);}
</script>

